import base64,json,pathlib,shlex,subprocess,time
source="import json,pathlib,subprocess,re,os,time,hashlib\nID=6814483810\nSLUGS=['alanna-pow','allison-parker','autumn-renae','briana-redd','cat-chase','dakota-lyn','dan-dangler','fit-sid','kyla-yesenosky','mrs-callace','olivia-jade','riley-mae-lewis','sania-mallory','tammy','toochi','trashy','tru-kait']\nroot=pathlib.Path('/home/ubuntu/twin-v2')\nmarker=root/'data'/'_rcy07_reset_20261013_receipt.json'\ninfo=json.loads(subprocess.check_output(['docker','inspect','twin-v2-bot-1'],text=True))[0]\nassert info['State']['Running'] and not info['State']['Paused'],'Bot unavailable or already paused'\nassert any(m['Source']==str(root/'data') and m['Destination']=='/app/data' for m in info['Mounts']),'Data mount changed'\nassert info['Image']=='sha256:9649329a00bd20fe06499f8238e1e51713381521af00d4cdc67505e1064f724a','Runtime changed; re-inspect before reset'\nneedle=re.compile(r'(?<!\\d)6814483810(?!\\d)|(?<![a-zA-Z0-9_])@?rcy07(?![a-zA-Z0-9_])',re.I)\nheader=re.compile(rb'^\\S+Z \\| (.*?) \\| ')\nprepared=[]\nreceipt={'at':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'telegramId':ID,'profiles':[],'logs':[],'paymentFilesUntouched':True,'messagesSent':0}\ndef atomic_json(p,value):\n p.parent.mkdir(parents=True,exist_ok=True)\n t=p.with_name(p.name+'.rcy07-reset.tmp')\n st=p.stat() if p.exists() else p.parent.stat()\n t.write_text(json.dumps(value,separators=(',',':')))\n os.chown(t,st.st_uid,st.st_gid);os.chmod(t,0o600 if p==marker else 0o644)\n os.replace(t,p)\ndef match_row(row):\n return isinstance(row,dict) and (str(row.get('chatId',''))==str(ID) or str(row.get('fan_id',''))==str(ID) or str(row.get('telegram_id',''))==str(ID) or str(row.get('fan',''))==str(ID))\ndef filter_line(line,kind,state):\n if kind=='jsonl':\n  try:r=json.loads(line)\n  except Exception:raise RuntimeError('Malformed app log; refusing to rewrite')\n  return match_row(r)\n h=header.match(line)\n if h:state['drop']=bool(needle.search(h.group(1).decode(errors='replace')))\n return state.get('drop',False)\nif not marker.exists():\n for slug in SLUGS:\n  p=root/'data'/slug/(str(ID)+'.json')\n  if p.exists():\n   c=json.loads(p.read_text())\n   assert not c.get('who') or c['who'].lower() in ['@rcy07','rcy07',str(ID)],'Fan identity mismatch'\n   assert time.time()-p.stat().st_mtime>30,'Target recently active; avoid clearing a new turn'\n  for fname in ['_archive_queue.jsonl','_archive_dead.jsonl']:\n   q=p.parent/fname\n   if q.exists():\n    assert not any(str(ID) in line for line in q.open()),'Archive work exists; drain before reset'\n for slug in SLUGS:\n  folder=root/'logs'/slug\n  if not folder.exists():continue\n  for p in folder.iterdir():\n   if not p.is_file() or p.name not in ['requests.jsonl','blocked.jsonl','payment-support.jsonl','turns.log']:continue\n   st=p.stat();tmp=p.with_name(p.name+'.rcy07-reset.tmp')\n   kind='jsonl' if p.suffix=='.jsonl' else 'blocks'\n   state={};removed=0;kept=0;blocks=0\n   with p.open('rb') as src,tmp.open('wb') as dst:\n    for line in src:\n     if not line.endswith(b'\\n'):raise RuntimeError('Incomplete log append; retry read-only preflight')\n     drop=filter_line(line,kind,state)\n     if drop:\n      removed+=1\n      if kind=='jsonl' or header.match(line):blocks+=1\n     else:dst.write(line);kept+=1\n    offset=src.tell()\n   if removed:prepared.append({'p':p,'tmp':tmp,'st':st,'kind':kind,'state':state,'offset':offset,'removed':removed,'kept':kept,'blocks':blocks})\n   else:tmp.unlink()\n # Only the final swaps run while writes are frozen; other fans' complete log rows are retained byte for byte.\n paused=False\n try:\n  subprocess.run(['docker','pause','twin-v2-bot-1'],check=True,capture_output=True);paused=True\n  for x in prepared:\n   st=x['p'].stat();assert st.st_ino==x['st'].st_ino and st.st_size>=x['offset'],'Log rotated; refusing replace'\n   with x['p'].open('rb') as src,x['tmp'].open('ab') as dst:\n    src.seek(x['offset'])\n    for line in src:\n     assert line.endswith(b'\\n'),'Incomplete log append while paused'\n     if filter_line(line,x['kind'],x['state']):\n      x['removed']+=1\n      if x['kind']=='jsonl' or header.match(line):x['blocks']+=1\n     else:dst.write(line);x['kept']+=1\n   os.chown(x['tmp'],st.st_uid,st.st_gid);os.chmod(x['tmp'],st.st_mode&0o777)\n  for slug in SLUGS:\n   p=root/'data'/slug/(str(ID)+'.json')\n   c=json.loads(p.read_text()) if p.exists() else {}\n   new={'ageConfirmed':False,'history':[],'sent':[],'epoch':int(c.get('epoch',0))+1,'who':c.get('who','@rcy07')}\n   if c.get('bcid'):new['bcid']=c['bcid']\n   atomic_json(p,new)\n   receipt['profiles'].append({'slug':slug,'previousMessages':len(c.get('history',[])),'previousSent':len(c.get('sent',[])),'epoch':new['epoch']})\n   q=p.parent/'_credit_state.json'\n   if q.exists():\n    v=json.loads(q.read_text());changed=False\n    for k in ['pending','offered']:\n     if isinstance(v.get(k),dict) and str(ID) in v[k]:del v[k][str(ID)];changed=True\n    if changed:atomic_json(q,v)\n  for x in prepared:\n   os.replace(x['tmp'],x['p'])\n   receipt['logs'].append({'file':str(x['p'].relative_to(root)),'removedRecords':x['blocks'],'removedLines':x['removed'],'otherLinesPreserved':x['kept']})\n  atomic_json(marker,receipt)\n finally:\n  if paused:subprocess.run(['docker','unpause','twin-v2-bot-1'],check=True,capture_output=True)\nelse:\n receipt=json.loads(marker.read_text())\n receipt['alreadyApplied']=True\n# Assert the exact live-reader data is empty; the ledger and payment caches were never edited.\nverify=[]\nfor slug in SLUGS:\n c=json.loads((root/'data'/slug/(str(ID)+'.json')).read_text())\n verify.append({'slug':slug,'history':len(c.get('history',[])),'sent':len(c.get('sent',[])),'hasPhotoContext':'photo' in c,'epoch':c['epoch']})\nassert all(x['history']==0 and x['sent']==0 and not x['hasPhotoContext'] for x in verify),'New chat activity or reset verification failed'\nremaining=[]\nfor slug in SLUGS:\n folder=root/'logs'/slug\n if not folder.exists():continue\n for p in folder.iterdir():\n  if p.name not in ['requests.jsonl','blocked.jsonl','payment-support.jsonl','turns.log']:continue\n  count=0;state={}\n  with p.open('rb') as src:\n   for line in src:\n    if filter_line(line,'jsonl' if p.suffix=='.jsonl' else 'blocks',state):count+=1\n  if count:remaining.append({'file':str(p.relative_to(root)),'rows':count})\nreceipt['verified']=verify;receipt['remainingAppLogRows']=remaining\nassert not remaining,'Target application logs remain'\nstate=json.loads(subprocess.check_output(['docker','inspect','twin-v2-bot-1'],text=True))[0]['State']\nassert state['Running'] and not state['Paused'],'Bot did not resume'\nreceipt['botRunning']=True\nprint('RESET_APPLIED '+json.dumps(receipt),flush=True)\nv1=pathlib.Path('/home/ubuntu/allieai2-bot')\nout=[]\nfor p in (v1/'src').rglob('*'):\n if p.is_file() and p.suffix in ['.ts','.js'] and 'dev' not in p.parts:\n  if any(k in p.name.lower() for k in ['supabase','store','cache','redis','profile']) or 'data' in p.relative_to(v1).parts:\n   lines=p.read_text(errors='replace').splitlines()\n   picks=[{'n':i+1,'s':l[:180]} for i,l in enumerate(lines) if re.search(r'cache|Map<|fan_profiles|chat_history|user_received|stated_name',l)]\n   out.append({'file':str(p.relative_to(v1)),'lines':len(lines),'hits':picks[:24]})\nprint('V1_CACHE_CHECK '+json.dumps(out[:16]),flush=True)\n"
command='python3 -c '+shlex.quote('import base64;exec(compile(base64.b64decode('+repr(base64.b64encode(source.encode()).decode())+'),"rcy07-preflight","exec"))')
p=pathlib.Path('/tmp/rcy07-ssm-params.json');p.write_text(json.dumps({'commands':[command],'executionTimeout':['120']}))
cid=subprocess.check_output(['aws','ssm','send-command','--instance-ids','i-0584d283506f3f6be','--document-name','AWS-RunShellScript','--parameters','file://'+str(p),'--comment','Authorized RCY07 all-creator chat and application log reset','--query','Command.CommandId','--output','text'],text=True).strip()
print('COMMAND '+cid,flush=True)
for _ in range(50):
 time.sleep(2)
 try:r=json.loads(subprocess.check_output(['aws','ssm','get-command-invocation','--command-id',cid,'--instance-id','i-0584d283506f3f6be','--output','json'],text=True,stderr=subprocess.DEVNULL))
 except subprocess.CalledProcessError:continue
 if r['Status'] in ['Success','Failed','Cancelled','TimedOut']:break
else:raise RuntimeError('SSM still running; inspect command '+cid)
